/* v9.2 · Contact page (from concepts/pages-12/p09-lets-talk.html). Generated by Claude (AI assistant) for Mohamed Dhia Beldi.
   Tunis local time, calm reveals, and the CV link follows the site language. The panel is lets-talk.js. */
(function () {
  'use strict';
  /* the mobile menu is bound once for every page in transitions.js */

  /* Tunis time; the element is looked up each tick because a language switch re-renders its sentence */
  var f = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Tunis', hour: '2-digit', minute: '2-digit', hour12: false });
  function t() { var el = document.getElementById('ct-time'); if (el) el.textContent = f.format(new Date()); }
  t(); setInterval(t, 15000);

  /* the plain CV link downloads the PDF in the site's language */
  function cv() {
    var fr = document.documentElement.lang === 'fr';
    [].forEach.call(document.querySelectorAll('[data-cv-site]'), function (a) {
      a.href = 'assets/cv-3a7b1ab257ba/Mohamed-Dhia-Beldi-CV-' + (fr ? 'FR' : 'EN') + '.pdf';
    });
  }
  cv();
  addEventListener('i18n:changed', function () { t(); cv(); });

  /* calm reveals */
  var els = document.querySelectorAll('.ct-rv');
  if (!('IntersectionObserver' in window) || matchMedia('(prefers-reduced-motion: reduce)').matches) {
    [].forEach.call(els, function (e) { e.classList.add('in'); }); return;
  }
  var io = new IntersectionObserver(function (es) {
    es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
  }, { rootMargin: '0px 0px -8% 0px' });
  [].forEach.call(els, function (e, i) {
    e.style.transitionDelay = (e.classList.contains('ct-card') ? (i % 3) * 90 : 0) + 'ms'; io.observe(e);
  });
})();
